     */
    protected function setUp(): void
    {
        $this->root = NativeTestWorkspace::create('push-transport');
        $path = $this->root . DIRECTORY_SEPARATOR . 'fixture.phx';
        file_put_contents($path, 'fixture-private-package');
        $this->package = new PreparedDeploymentResult($path, hash_file('sha256', $path), 'fixture');
