     */
    private function receipt(int $status): array
    {
        return ['protocol' => 'axenox.Deployer.native-ota/1', 'deployment_id' => 'attempt-1',
            'sha256' => $this->package->sha256, 'status' => $status];
    }

    /**
     * @return void
     */
    public function testConnectionAuthenticationPathUsesSecureOptionsAndVerifiedReceipt(): void
    {
        $connection = $this->getMockBuilder(HttpConnector::class)->disableOriginalConstructor()
            ->onlyMethods(['getUrl', 'sendRequest'])->getMock();
        $connection->method('getUrl')->willReturn('https://fixture.invalid/installation');
        $connection->expects(self::once())->method('sendRequest')->willReturnCallback(function ($request, $options) {
            self::assertSame('https://fixture.invalid/installation/api/updater/native-push', (string) $request->getUri());
            self::assertSame('fixture-private-package', (string) $request->getBody());
            self::assertSame('attempt-1', $request->getHeaderLine('X-Deployer-Deployment'));
            self::assertSame($this->package->sha256, $request->getHeaderLine('X-Deployer-SHA256'));
            self::assertSame('ota-' . hash('sha256', 'attempt-1') . '.phx', $request->getHeaderLine('X-Deployer-Filename'));
            self::assertTrue($options['verify']);
            self::assertSame([64 => true, 81 => 2], $options['curl']);
            self::assertFalse($options['allow_redirects']);
            self::assertSame(10, $options['connect_timeout']);
            self::assertSame(900, $options['timeout']);
            self::assertArrayNotHasKey('auth', $options);
            return new Response(200, [], json_encode($this->receipt(99)));
        });
        self::assertSame(99, NativePushTransport::upload($connection, $this->package, 'attempt-1'));
    }

