    public function testPreservationSettingsRoundtripWithoutConnectionOrHostInputs(): void
    {
        $pipeline = new UpdaterPush($this->createStub(WorkbenchInterface::class));
        $pipeline->importUxonObject(new UxonObject(['keep_releases' => 8, 'php_memory_limit' => '3G',
            'local_packages' => ['example/local'], 'deadline_seconds' => 120]));
        $settings = $pipeline->exportUxonObject()->toArray();
        $copy = new UpdaterPush($this->createStub(WorkbenchInterface::class));
        $copy->importUxonObject(new UxonObject($settings));
